insert into itera.bounty_templates (key, active, keep_open, daily_cap, payload) values ('judge-bounty', false, 2, 40, $j${"sponsor_name": "Itera team", "title_i18n": {"en": "Judge bounty: your first page", "pt": "Bounty do jurado: sua primeira página"}, "summary_i18n": {"en": "A two-minute task judged by a check, not by a person. Made for judges and first-timers who want to see the escrow pay their own wallet.", "pt": "Uma tarefa de dois minutos julgada por uma verificação, não por uma pessoa. Feita para jurados e para quem quer ver o escrow pagar a própria carteira."}, "brief_i18n": {"en": "Write one small HTML page, the kind Day 1 teaches: a doctype, a head with a title, and a body with one h1 and one paragraph about what you want to build. Paste the code on this page. The same engine that grades the lessons reads it; when the five checks pass, the escrow program pays the reward to your wallet in the same minute. Nobody at Itera reviews it. One payout per learner and per wallet.", "pt": "Escreva uma página HTML pequena, do tipo que o Dia 1 ensina: um doctype, um head com title e um body com um h1 e um parágrafo sobre o que você quer construir. Cole o código nesta página. O mesmo motor que corrige as aulas lê o código; quando as cinco verificações passam, o programa de escrow paga a recompensa para a sua carteira no mesmo minuto. Ninguém da Itera revisa. Um pagamento por aluno e por carteira."}, "deliverable_i18n": {"en": "The HTML code, pasted on this page. Five checks: a doctype, a title inside the head, one h1, one paragraph, every tag closed.", "pt": "O código HTML, colado nesta página. Cinco verificações: doctype, um title dentro do head, um h1, um parágrafo, todas as tags fechadas."}, "unit_id": "9624052c-4efb-49ca-8bbf-f63d0e5d6c2d", "min_days": 1, "reward_lamports": 10000000, "claim_hours": 1, "expires_days": 3, "auto_check": {"version": 1, "language": "html", "checks": [{"id": "doctype", "label": {"en": "Starts with <!DOCTYPE html>", "pt": "Começa com <!DOCTYPE html>"}, "assert": {"type": "source_has", "tag": "doctype"}}, {"id": "title", "label": {"en": "A <title> inside the <head>", "pt": "Um <title> dentro do <head>"}, "selector": "head > title", "assert": {"type": "exists"}}, {"id": "h1", "label": {"en": "One <h1> in the <body>", "pt": "Um <h1> no <body>"}, "selector": "body h1", "assert": {"type": "count", "equals": 1}}, {"id": "p", "label": {"en": "At least one <p> in the <body>", "pt": "Pelo menos um <p> no <body>"}, "selector": "body p", "assert": {"type": "exists"}}, {"id": "closed", "label": {"en": "html, head, title, body, h1 and p are all closed", "pt": "html, head, title, body, h1 e p estão todos fechados"}, "selector": "html, head, title, body, h1, p", "assert": {"type": "closes"}}]}}$j$::jsonb) on conflict (key) do update set payload = excluded.payload;